create table if not exists public.incomes (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches(id), income_date date not null default current_date, category text not null, amount numeric(14,2) not null check(amount>0), payment_method text not null check(payment_method in ('cash','qr','transfer','card','other')), payer_name text, note text, recorded_by_user_id uuid not null references public.users(id), created_at timestamptz not null default now());
create table if not exists public.expenses (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches(id), expense_date date not null default current_date, category text not null, amount numeric(14,2) not null check(amount>0), payment_method text not null check(payment_method in ('cash','qr','transfer','card','other')), payee_name text, note text, status text not null default 'pending' check(status in ('pending','approved','rejected','paid')), recorded_by_user_id uuid not null references public.users(id), approved_by_user_id uuid references public.users(id), approved_at timestamptz, created_at timestamptz not null default now());
create index if not exists incomes_branch_date_idx on public.incomes(branch_id,income_date desc); create index if not exists expenses_branch_status_date_idx on public.expenses(branch_id,status,expense_date desc);
alter table public.incomes enable row level security; alter table public.expenses enable row level security; revoke all on public.incomes,public.expenses from anon,authenticated; grant all on public.incomes,public.expenses to service_role; create policy commerce_server_only on public.incomes for all to authenticated using(false) with check(false); create policy commerce_server_only on public.expenses for all to authenticated using(false) with check(false);
